import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

export function createDecoder(){
  const textDecoder=new TextDecoder('utf-8',{fatal:true});
  let lineBuffer='';
  let dataLines=[];
  let currentEvent;
  let terminated=false;
  let finished=false;
  let poisoned=false;

  function fail(message){
    poisoned=true;
    throw new Error(message);
  }

  function processLine(rawLine, frames){
    if(terminated){
      if(rawLine!=='')fail('nonblank line after termination marker');
      return;
    }
    if(rawLine===''){
      if(dataLines.length>0){
        const data=dataLines.join('\n');
        const eventName=(currentEvent===undefined||currentEvent==='')?'message':currentEvent;
        dataLines=[];
        currentEvent=undefined;
        if(data==='[DONE]'){
          terminated=true;
        }else{
          frames.push({event:eventName,data});
        }
      }else{
        currentEvent=undefined;
      }
      return;
    }
    if(rawLine.startsWith(':'))return;
    const idx=rawLine.indexOf(':');
    let name,value;
    if(idx===-1){
      name=rawLine;
      value='';
    }else{
      name=rawLine.slice(0,idx);
      value=rawLine.slice(idx+1);
      if(value.startsWith(' '))value=value.slice(1);
    }
    if(name==='data')dataLines.push(value);
    else if(name==='event')currentEvent=value;
  }

  return {
    push(chunk){
      if(poisoned)throw new Error('decoder is poisoned');
      if(finished)fail('push after finish');
      if(!(chunk instanceof Uint8Array))fail('chunk must be a Uint8Array');
      let text;
      try{
        text=textDecoder.decode(chunk,{stream:true});
      }catch(error){
        poisoned=true;
        throw new Error('invalid UTF-8 sequence');
      }
      lineBuffer+=text;
      const parts=lineBuffer.split('\n');
      lineBuffer=parts.pop();
      const frames=[];
      try{
        for(let raw of parts){
          if(raw.endsWith('\r'))raw=raw.slice(0,-1);
          processLine(raw,frames);
        }
      }catch(error){
        throw error;
      }
      return frames;
    },
    finish(){
      if(poisoned)throw new Error('decoder is poisoned');
      if(finished)fail('finish called after finish already succeeded');
      let text;
      try{
        text=textDecoder.decode();
      }catch(error){
        poisoned=true;
        throw new Error('incomplete UTF-8 sequence at end of stream');
      }
      lineBuffer+=text;
      if(lineBuffer!=='')fail('unterminated final line');
      if(!terminated)fail('stream missing termination marker');
      if(dataLines.length>0||currentEvent!==undefined)fail('pending frame fields at finish');
      finished=true;
      return [];
    },
  };
}

function isCanonicalBase64(s){
  if(typeof s!=='string')return false;
  if(!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(s))return false;
  const buf=Buffer.from(s,'base64');
  return buf.toString('base64')===s;
}

function runCli(){
  try{
    if(process.argv.length!==3)throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
    const raw=fs.readFileSync(process.argv[2],'utf8');
    const input=JSON.parse(raw);
    if(typeof input!=='object'||input===null||Array.isArray(input))throw new Error('input must be a JSON object');
    if(!Array.isArray(input.chunks))throw new Error('chunks must be an array');
    const buffers=[];
    for(const encoded of input.chunks){
      if(!isCanonicalBase64(encoded))throw new Error('chunk is not canonical base64');
      buffers.push(Buffer.from(encoded,'base64'));
    }
    const decoder=createDecoder();
    const frames=[];
    for(const buf of buffers)frames.push(...decoder.push(buf));
    frames.push(...decoder.finish());
    process.stdout.write(JSON.stringify({frames})+'\n');
  }catch(error){
    process.stderr.write(String(error.message)+'\n');
    process.exitCode=2;
  }
}

if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
  runCli();
}

