  try { d.push(new Uint8Array()); console.log('FAIL should be poisoned'); } catch(e) { console.log('poisoned ok'); }

  // incomplete multibyte at finish
  d = createDecoder();
  d.push(Uint8Array.of(0xE2, 0x82)); // incomplete euro sign
  try { d.finish(); console.log('FAIL no throw'); } catch(e) { console.log('incomplete at finish throws ok:', e.message); }

  // unterminated final line
  d = createDecoder();
  d.push(Buffer.from('data: [DONE]\n\ndata: oops'));
  try { d.finish(); console.log('FAIL'); } catch(e) { console.log('unterminated line ok:', e.message); }

  // second DONE marker throws
  d = createDecoder();
  d.push(Buffer.from('data: [DONE]\n\n'));
  try { d.push(Buffer.from('data: [DONE]\n\n')); console.log('FAIL'); } catch(e) { console.log('second done throws ok'); }

  // comment lines ignored
  d = createDecoder();
  f = d.push(Buffer.from(':comment\ndata: y\n\ndata: [DONE]\n\n'));
  d.finish();
  assert.deepEqual(f, [{event:'message', data:'y'}]);
  console.log('comment ok');

  // no colon line -> field name whole line, empty value; unknown field ignored, but 'data' with no colon still counts as data field with '' value
  d = createDecoder();
  f = d.push(Buffer.from('data\n\ndata: [DONE]\n\n'));
  d.finish();
  assert.deepEqual(f, [{event:'message', data:''}]);
  console.log('no-colon data ok');

  console.log('ALL DONE');
}).catch(e=>{console.error('ERR', e); process.exit(1);});
